func TestPromotionRejectsInvalidEvidenceBeforeEffects(t *testing.T) {
	for _, tc := range []struct {
		name, message string
		prepare       func(*promotionFixture)
		env           map[string]string
	}{
		{"failed-run", "image.yml run did not succeed", func(f *promotionFixture) { f.writeRun("failure", "success") }, nil},
		{"wrong-run-number", "image.yml run did not succeed", func(f *promotionFixture) {
			path := filepath.Join(f.fixture, "run-detail/11738.json")
			write(f.t, path, []byte(strings.Replace(string(read(f.t, path)), `"run_number":713`, `"run_number":714`, 1)), 0600)
		}, nil},
		{"wrong-run-branch", "GitHub release proof must originate", func(f *promotionFixture) {
			path := filepath.Join(f.fixture, "run-detail/11738.json")
			write(f.t, path, []byte(strings.Replace(string(read(f.t, path)), `"head_branch":"main"`, `"head_branch":"other"`, 1)), 0600)
		}, nil},
		{"wrong-run-event", "GitHub release proof must originate", func(f *promotionFixture) {
			path := filepath.Join(f.fixture, "run-detail/11738.json")
			write(f.t, path, []byte(strings.Replace(string(read(f.t, path)), `"event":"workflow_dispatch"`, `"event":"pull_request"`, 1)), 0600)
		}, nil},
		{"failed-attempt", "image job did not succeed on this attempt", func(f *promotionFixture) { f.writeRun("success", "failure") }, nil},
		{"missing-marker", "lacks one exact TS_IMAGE_QUALIFICATION_V1 marker", func(f *promotionFixture) {
			write(f.t, filepath.Join(f.fixture, "logs/25300.txt"), []byte("no marker\n"), 0600)
		}, nil},
		{"tampered-image", "image asset differs from SHA256SUMS: terrascale-gru-arm64.qcow2", func(f *promotionFixture) {
			write(f.t, filepath.Join(f.imageDir, "terrascale-gru-arm64.qcow2"), []byte("tampered"), 0600)
		}, nil},
		{"wrong-binary", "candidate release " + goTag + " differs from the image manifest", func(f *promotionFixture) {
			f.writeRelease(goTag, map[string][]byte{"terrascale-orchestrator-linux-arm64": []byte("other")})
		}, nil},
		{"rejected-receipt", "ts-orch release verify-binary failed", func(*promotionFixture) {}, map[string]string{"PROMOTE_FAIL_RELEASE": "verify-binary"}},
		{"missing-production-proof", "retained image evidence unavailable", func(f *promotionFixture) {
			path := filepath.Join(f.fixture, "releases/TerraScale_ts-orchestrator", goTag, "image-production-"+digest(f.image)+"-GRU-arm64.json")
			if err := os.Remove(path); err != nil {
				f.t.Fatal(err)
			}
		}, nil},
		{"tampered-production-evidence", "retained image evidence bytes differ", func(f *promotionFixture) {
			evidence := []byte("test-only final image runtime-ha evidence")
			f.writeRelease(goTag, map[string][]byte{"image-production-evidence-" + digest(evidence): []byte(strings.Repeat("x", len(evidence)))})
		}, nil},
		{"untrusted-production-proof", "final image production qualification", func(f *promotionFixture) {
			public, _, err := ed25519.GenerateKey(rand.Reader)
			if err != nil {
				f.t.Fatal(err)
			}
			der, err := x509.MarshalPKIXPublicKey(public)
			if err != nil {
				f.t.Fatal(err)
			}
			write(f.t, filepath.Join(f.trust, "root.pub"), pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: der}), 0600)
		}, nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f := newPromotion(t)
			tc.prepare(f)
			f.rejected(f.promote(nil, tc.env, f.realArgs()...), tc.message)
		})
	}
}

