func absent(t *testing.T, path string) {
	t.Helper()
	if _, err := os.Lstat(path); !os.IsNotExist(err) {
		t.Fatalf("%s exists or could not be inspected: %v", path, err)
	}
}

func Start(t testing.TB, imageID string) *Server {
	t.Helper()
	s := &Server{imageID: imageID, created: time.Now().UTC().Truncate(time.Second), objects: map[string]object{},
		work: map[string]int{}, workIDs: map[string]string{}, shapes: map[string][]shape{},
		uploads: map[string]*upload{}}
	server := httptest.NewServer(s.handler())
	t.Cleanup(server.Close)
	s.URL = server.URL
	return s
}

// Requests returns every request served so far as "METHOD /path".
func (s *Server) Requests() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return slices.Clone(s.requests)
}

// Count returns how many served requests start with prefix.
func (s *Server) Count(prefix string) int {
	count := 0
	for _, request := range s.Requests() {
		if strings.HasPrefix(request, prefix) {
			count++
		}
	}
	return count
}

// Object returns a stored object's bytes and user metadata.
func (s *Server) Object(namespace, bucket, name string) ([]byte, map[string]string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	stored, ok := s.objects[namespace+"/"+bucket+"/"+name]
	return stored.data, stored.metadata, ok
}

// Image returns the lifecycle state of a stored image.
func (s *Server) Image(id string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, stored := range s.images {
		if stored.ID == id {
			return stored.State, true
		}
	}
	return "", false
}

func (s *Server) handler() http.Handler {
	mux := http.NewServeMux()
	const core = "/20160918"
	mux.HandleFunc("HEAD /n/{namespace}/b/{bucket}/o/{object...}", s.headObject)
	mux.HandleFunc("PUT /n/{namespace}/b/{bucket}/o/{object...}", s.putObject)
	s.routeMultipart(mux)
	mux.HandleFunc("GET "+core+"/images", s.listImages)
	mux.HandleFunc("POST "+core+"/images", s.createImage)
	mux.HandleFunc("GET "+core+"/images/{id}", s.getImage)
	mux.HandleFunc("GET "+core+"/workRequests/{id}", s.getWorkRequest)
	mux.HandleFunc("GET "+core+"/computeImageCapabilitySchemas", s.listSchemas)
	mux.HandleFunc("POST "+core+"/computeImageCapabilitySchemas", s.createSchema)
	mux.HandleFunc("GET "+core+"/computeImageCapabilitySchemas/{id}", s.getSchema)
	mux.HandleFunc("GET "+core+"/computeGlobalImageCapabilitySchemas", func(w http.ResponseWriter, r *http.Request) {
		// The first page is empty and points at the next one, so the
		// client must follow pagination to find the schema.
		if r.URL.Query().Get("page") == "" {
			w.Header().Set("opc-next-page", "global-schemas-2")
			reply(w, http.StatusOK, []map[string]string{})
			return
		}
		reply(w, http.StatusOK, []map[string]string{{"id": "ocid1.computeglobalimgcapschema.standin", "currentVersionName": "standin-v1"}})
	})
	mux.HandleFunc("GET "+core+"/images/{id}/shapes", s.listShapes)
	mux.HandleFunc("PUT "+core+"/images/{id}/shapes/{shape}", s.addShape)
	mux.HandleFunc("DELETE "+core+"/images/{id}/shapes/{shape}", s.removeShape)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Every SDK request is signed; an unsigned request is not the client
		// under test.
		if !strings.HasPrefix(r.Header.Get("Authorization"), "Signature ") {
			refuse(w, http.StatusUnauthorized, "NotAuthenticated", "unsigned request")
			return
		}
		s.mu.Lock()
		s.requests = append(s.requests, r.Method+" "+r.URL.Path)
		s.mu.Unlock()
		mux.ServeHTTP(w, r)
	})
}

func objectKey(r *http.Request) string {
	return r.PathValue("namespace") + "/" + r.PathValue("bucket") + "/" + r.PathValue("object")
}

func (s *Server) headObject(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	stored, ok := s.objects[objectKey(r)]
	s.mu.Unlock()
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	for key, value := range stored.metadata {
		w.Header().Set("opc-meta-"+key, value)
	}
	w.Header().Set("Content-Length", fmt.Sprint(len(stored.data)))
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) putObject(w http.ResponseWriter, r *http.Request) {
	data, err := io.ReadAll(r.Body)
	if err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	if want := r.Header.Get("Content-MD5"); want != "" && want != contentMD5(data) {
		refuse(w, http.StatusBadRequest, "InvalidContentMD5", "object MD5 mismatch")
		return
	}
	metadata := map[string]string{}
	for key, values := range r.Header {
		if name, ok := strings.CutPrefix(strings.ToLower(key), "opc-meta-"); ok && len(values) > 0 {
			metadata[name] = values[0]
		}
	}
	key := objectKey(r)
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.objects[key]; exists && r.Header.Get("If-None-Match") == "*" {
		refuse(w, http.StatusPreconditionFailed, "IfNoneMatchFailed", "object exists")
		return
	}
	s.objects[key] = object{data: data, metadata: metadata}
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) createImage(w http.ResponseWriter, r *http.Request) {
	var request createImage
	if err := json.UnmarshalRead(r.Body, &request); err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	if r.Header.Get("opc-retry-token") == "" || request.Source.Type != "objectStorageTuple" || request.Source.SourceImageType != "QCOW2" || request.LaunchMode != "PARAVIRTUALIZED" {
		refuse(w, http.StatusBadRequest, "InvalidParameter", "unexpected CreateImage request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.objects[request.Source.Namespace+"/"+request.Source.Bucket+"/"+request.Source.Object]; !ok {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "source object not found")
		return
	}
	id := s.imageID
	if len(s.images) > 0 {
		id = fmt.Sprintf("%s.%d", s.imageID, len(s.images))
	}
	created := &image{ID: id, CompartmentID: request.CompartmentID, DisplayName: request.DisplayName, State: "IMPORTING",
		Billable: BillableSizeGB, TimeCreated: s.created.Format(time.RFC3339), FreeformTags: request.FreeformTags}
	s.images = append(s.images, created)
	work := fmt.Sprintf("ocid1.coreservicesworkrequest.standin.%d", len(s.work)+1)
	s.work[work] = WorkRequestPolls
	s.workIDs[work] = id
	w.Header().Set("opc-work-request-id", work)
	reply(w, http.StatusOK, created)
}

func (s *Server) getImage(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	stored := s.find(r.PathValue("id"))
	if stored == nil {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "image not found")
		return
	}
	reply(w, http.StatusOK, stored)
}

func (s *Server) getWorkRequest(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	s.mu.Lock()
	defer s.mu.Unlock()
	remaining, ok := s.work[id]
	if !ok {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "work request not found")
		return
	}
	status := "SUCCEEDED"
	if remaining > 0 {
		status = "IN_PROGRESS"
		s.work[id] = remaining - 1
	} else if stored := s.find(s.workIDs[id]); stored != nil {
		stored.State = "AVAILABLE"
	}
	reply(w, http.StatusOK, map[string]any{"id": id, "operationType": "ImportImage", "status": status,
		"compartmentId": "standin", "percentComplete": 0, "timeAccepted": s.created.Format(time.RFC3339)})
}

func Client(endpoint, region string) (imageimport.API, error) {
	key, err := signingKey()
	if err != nil {
		return nil, err
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..standin", "ocid1.user.oc1..standin", region,
		"00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00", key, nil)
	factory, err := ociclient.New(provider, ociclient.Options{Region: region,
		Retry: ociclient.RetryOptions{MaxAttempts: 1}})
	if err != nil {
		return nil, err
	}
	return imageimport.NewClient(factory, endpoint)
}

// Importer returns an ImporterFactory whose importers drive the real SDK
// client against the stand-in at endpoint, polling every millisecond.
func Importer(endpoint string) imageimport.ImporterFactory {
	return func(region string) (imageimport.Importer, error) {
		client, err := Client(endpoint, region)
		if err != nil {
			return imageimport.Importer{}, err
		}
		return imageimport.Importer{Client: client, PollInterval: time.Millisecond, MaxPollInterval: 5 * time.Millisecond,
			AvailabilityTimeout: time.Minute}, nil
	}
}

func RunImporters(ctx context.Context, args []string, out io.Writer, importers ImporterFactory) error {
	fs := flag.NewFlagSet("oci-region import-image", flag.ContinueOnError)
	fs.SetOutput(out)
	var o Options
	var regions regionList
	fs.StringVar(&o.QCOW2, "qcow2", "", "qualified QCOW2 file")
	fs.StringVar(&o.SHA256, "sha256", "", "expected QCOW2 SHA-256")
	fs.Var(&regions, "region", "catalog OCI region; repeatable or comma-separated (default "+catalog.OCIRegion(catalog.Bootstrap)+")")
	fs.StringVar(&o.Compartment, "compartment-id", "", "image compartment")
	fs.StringVar(&o.Namespace, "namespace", "", "object namespace")
	fs.StringVar(&o.Bucket, "bucket", "", "object bucket (same name in every region)")
	fs.StringVar(&o.DisplayName, "display-name", "", "image display name")
	fs.StringVar(&o.Out, "out", "", "output record")
	fs.IntVar(&o.PartSizeMiB, "part-size-mib", defaultPartSizeMiB, "multipart upload part size in MiB")
	fs.IntVar(&o.UploadParallelism, "upload-parallelism", defaultUploadParallelism, "concurrent multipart upload parts")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}
	if fs.NArg() != 0 {
		return fmt.Errorf("unexpected arguments: %v", fs.Args())
	}
	o.Regions = regions
	if len(o.Regions) == 0 {
		o.Regions = []string{catalog.OCIRegion(catalog.Bootstrap)}
	}
	_, err := ImportRegions(ctx, o, out, importers)
	return err
}

func (i Importer) FindImage(ctx context.Context, compartment, name string) (*Image, error) {
	images, err := i.Client.ListImages(ctx, compartment, name)
	if err != nil {
		return nil, err
	}
	var live *Image
	for _, image := range images {
		if slices.Contains(liveImageStates, image.LifecycleState) {
			if live != nil {
				return nil, fmt.Errorf("more than one live image is named %s", name)
			}
			live = &image
		}
	}
	return live, nil
}

// WaitAvailable waits for the import work request, when known, and then for
// the image to report AVAILABLE. Polls start at PollInterval (5s) and double
// up to MaxPollInterval so short imports finish quickly without hammering OCI
// during long ones.
func (i Importer) WaitAvailable(ctx context.Context, id, workRequest string) (Image, error) {
	timeout := i.AvailabilityTimeout
	if timeout <= 0 {
		timeout = 45 * time.Minute
	}
	interval := i.PollInterval
	if interval <= 0 {
		interval = 5 * time.Second
	}
	ceiling := i.MaxPollInterval
	if ceiling <= 0 {
		ceiling = 60 * time.Second
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	for {
		if workRequest != "" {
			status, err := i.Client.GetWorkRequest(ctx, workRequest)
			if err != nil {
				return Image{}, err
			}
			switch status {
			case WorkRequestSucceeded:
				workRequest = ""
			case WorkRequestAccepted, WorkRequestInProgress:
			default:
				return Image{}, fmt.Errorf("image %s import work request %s ended %s", id, workRequest, status)
			}
		}
		if workRequest == "" {
			image, err := i.Client.GetImage(ctx, id)
			if err != nil {
				return Image{}, err
			}
			switch image.LifecycleState {
			case "AVAILABLE":
				return image, nil
			case "IMPORTING", "PROVISIONING":
			default:
				return Image{}, fmt.Errorf("image %s entered %v", id, image.LifecycleState)
			}
		}
		if err := i.pause(ctx, interval); err != nil {
			return Image{}, fmt.Errorf("image %s did not become AVAILABLE: %w", id, err)
		}
		interval = min(interval*2, ceiling)
	}
}

func (i Importer) EnsureCapabilities(ctx context.Context, compartment, id, name string) (CapabilitySchema, error) {
	ids, err := i.Client.ListCapabilitySchemas(ctx, compartment, id)
	if err != nil {
		return CapabilitySchema{}, err
	}
	var schema CapabilitySchema
	if len(ids) > 0 {
		if ids[0] == "" {
			return CapabilitySchema{}, errors.New("OCI capability schema has no id")
		}
		schema, err = i.Client.GetCapabilitySchema(ctx, ids[0])
		if err != nil {
			return CapabilitySchema{}, err
		}
	} else {
		version, err := i.Client.GlobalCapabilitySchemaVersion(ctx)
		if err != nil {
			return CapabilitySchema{}, err
		}
		if version == "" {
			return CapabilitySchema{}, errors.New("global schema has no version")
		}
		runes := []rune(name)
		if len(runes) > 255 {
			name = string(runes[:255])
		}
		schema, err = i.Client.CreateCapabilitySchema(ctx, compartment, id, name, version, Capabilities())
		if err != nil {
			return CapabilitySchema{}, err
		}
	}
	if schema.ID == "" {
		return CapabilitySchema{}, errors.New("OCI capability schema has no id")
	}
	for key, expected := range Capabilities() {
		actual, ok := schema.Data[key]
		if !ok || !actual.equal(expected) {
			return CapabilitySchema{}, fmt.Errorf("image capability %s differs from the launch contract", key)
		}
	}
	return schema, nil
}

func (i Importer) EnsureShapes(ctx context.Context, id string) ([]ShapeEntry, error) {
	entries, err := i.Client.ListShapes(ctx, id)
	if err != nil {
		return nil, err
	}
	index := slices.IndexFunc(entries, func(entry ShapeEntry) bool { return entry.Shape == A1Shape })
	if index < 0 || !a1Constraints(entries[index]) {
		if err := i.Client.AddShape(ctx, id, ShapeEntry{Shape: A1Shape, OCPU: new(a1OCPU), MemoryGB: new(a1Memory)}); err != nil {
			return nil, err
		}
	}
	for _, entry := range entries {
		if entry.Shape == "" {
			return nil, errors.New("shape compatibility row lacks shape")
		}
		if entry.Shape != A1Shape && !strings.HasSuffix(entry.Shape, ".Generic") {
			if err := i.Client.RemoveShape(ctx, id, entry.Shape); err != nil {
				return nil, err
			}
		}
	}
	entries, err = i.Client.ListShapes(ctx, id)
	if err != nil {
		return nil, err
	}
	found := false
	for _, entry := range entries {
		if entry.Shape == "" {
			return nil, errors.New("shape compatibility row lacks shape")
		}
		if entry.Shape == A1Shape {
			found = true
			if !a1Constraints(entry) {
				return nil, errors.New("image A1 constraints differ from the launch contract")
			}
		}
		if entry.Shape != A1Shape && !strings.HasSuffix(entry.Shape, ".Generic") {
			return nil, errors.New("image shape compatibility is not A1-only")
		}
	}
	if !found {
		return nil, errors.New("image shape compatibility is not A1-only")
	}
	return entries, nil
}

func ImportRegions(ctx context.Context, o Options, out io.Writer, importer func(region string) (Importer, error)) (map[string]any, error) {
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	if err := o.validate(); err != nil {
		return nil, err
	}
	if err := verifyDigest(o.QCOW2, o.SHA256); err != nil {
		return nil, err
	}
	var (
		mu          sync.Mutex
		wg          sync.WaitGroup
		records     = make(map[string]map[string]any, len(o.Regions))
		errs        = make([]error, len(o.Regions))
		done        = make([]bool, len(o.Regions))
		checkpoints []error
	)
	result := func() map[string]any {
		if len(o.Regions) == 1 && records[o.Regions[0]] != nil {
			return records[o.Regions[0]]
		}
		regions := make(map[string]any, len(records))
		for region, record := range records {
			regions[region] = record
		}
		r := map[string]any{"schema": "terrascale.oci.image-import-set.v1", "qcow2_sha256": o.SHA256, "display_name": o.DisplayName, "regions": regions}
		failures := map[string]string{}
		var pending []string
		for index, region := range o.Regions {
			if !done[index] {
				pending = append(pending, region)
			}
			if errs[index] != nil {
				failures[region] = errs[index].Error()
			}
		}
		if len(failures) > 0 {
			r["errors"] = failures
		}
		if len(pending) > 0 {
			r["pending"] = pending
		}
		return r
	}
	if err := writeImportCheckpoint(o.Out, result()); err != nil {
		return nil, err
	}
	logf := func(format string, args ...any) {
		mu.Lock()
		defer mu.Unlock()
		_, _ = fmt.Fprintf(out, format, args...)
	}
	semaphore := make(chan struct{}, 3)
	for index, region := range o.Regions {
		semaphore <- struct{}{}
		wg.Go(func() {
			defer func() { <-semaphore }()
			var record map[string]any
			regional, err := importer(region)
			if err == nil {
				record, err = regional.importVerified(ctx, o, func(format string, args ...any) {
					if len(o.Regions) > 1 {
						format = region + ": " + format
					}
					logf(format, args...)
				})
			}
			mu.Lock()
			defer mu.Unlock()
			done[index] = true
			if err != nil {
				errs[index] = fmt.Errorf("%s: %w", region, err)
			} else {
				records[region] = record
			}
			if err := writeImportCheckpoint(o.Out, result()); err != nil {
				checkpoints = append(checkpoints, fmt.Errorf("checkpoint %s: %w", region, err))
			}
		})
	}
	wg.Wait()
	final := result()
	b, err := json.Marshal(final, json.Deterministic(true))
	if err != nil {
		return final, errors.Join(errors.Join(errs...), errors.Join(checkpoints...), err)
	}
	_, err = fmt.Fprintln(out, string(b))
	return final, errors.Join(errors.Join(errs...), errors.Join(checkpoints...), err)
}

func (i Importer) importVerified(ctx context.Context, o Options, logf func(string, ...any)) (map[string]any, error) {
	objectName := "images/" + o.SHA256 + ".qcow2"
	image, err := i.FindImage(ctx, o.Compartment, o.DisplayName)
	if err != nil {
		return nil, err
	}
	// Display names are static (gru-1-arm64), so a live image of this name
	// may hold another QCOW2. Resume only the import of these exact bytes.
	if image != nil && image.SHA256 != o.SHA256 {
		return nil, fmt.Errorf("live image %s is named %s but holds QCOW2 %q, not %s; retire it before importing",
			image.ID, o.DisplayName, image.SHA256, o.SHA256)
	}
	workRequest := ""
	if image == nil {
		exists, metadata, err := i.Client.HeadObject(ctx, o.Namespace, o.Bucket, objectName)
		if err != nil {
			return nil, err
		}
		if exists && metadata["sha256"] != "" && metadata["sha256"] != o.SHA256 {
			return nil, fmt.Errorf("object %s carries a different sha256 metadata value", objectName)
		}
		if !exists {
			logf("uploading %s\n", objectName)
			partSize := o.PartSizeMiB
			if partSize == 0 {
				partSize = defaultPartSizeMiB
			}
			parallelism := o.UploadParallelism
			if parallelism == 0 {
				parallelism = defaultUploadParallelism
			}
			if err := i.Client.UploadObject(ctx, UploadRequest{Namespace: o.Namespace, Bucket: o.Bucket, Object: objectName,
				Path: o.QCOW2, SHA256: o.SHA256, Metadata: map[string]string{"sha256": o.SHA256},
				PartSize: int64(partSize) << 20, Parallelism: parallelism}); err != nil {
				return nil, err
			}
		}
		logf("importing image\n")
		created, request, err := i.Client.ImportImage(ctx, ImportRequest{Compartment: o.Compartment, Namespace: o.Namespace,
			Bucket: o.Bucket, Object: objectName, DisplayName: o.DisplayName, SHA256: o.SHA256})
		if err != nil {
			return nil, err
		}
		image, workRequest = &created, request
	}
	if image.ID == "" {
		return nil, errors.New("OCI image has no id")
	}
	id := image.ID
	available, err := i.WaitAvailable(ctx, id, workRequest)
	if err != nil {
		return nil, err
	}
	schema, err := i.EnsureCapabilities(ctx, o.Compartment, id, o.DisplayName)
	if err != nil {
		return nil, err
	}
	shapes, err := i.EnsureShapes(ctx, id)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(shapes))
	for _, entry := range shapes {
		names = append(names, entry.Shape)
	}
	slices.Sort(names)
	var billable any
	if available.BillableSizeGB != nil {
		billable = *available.BillableSizeGB
	}
	return map[string]any{"schema": "terrascale.oci.image-import.v1", "image_id": id, "display_name": o.DisplayName,
		"qcow2_sha256": o.SHA256, "compartment_id": o.Compartment, "object": o.Namespace + "/" + o.Bucket + "/" + objectName,
		"billable_size_gb": billable, "capability_schema_id": schema.ID, "shapes": names}, nil
}

func newSDKClient(factory *ociclient.Factory, endpoint string) (*sdkClient, error) {
	compute, err := factory.Compute()
	if err != nil {
		return nil, err
	}
	objects, err := factory.ObjectStorage()
	if err != nil {
		return nil, err
	}
	work, err := factory.WorkRequests()
	if err != nil {
		return nil, err
	}
	ociclient.PinHost(&compute.BaseClient, endpoint)
	ociclient.PinHost(&objects.BaseClient, endpoint)
	ociclient.PinHost(&work.BaseClient, endpoint)
	return &sdkClient{compute: compute, objects: objects, workRequest: work,
		uploadRetry: ociclient.IdempotentPutRetryPolicy(ociclient.RetryOptions{})}, nil
}

func page(next *string) (*string, bool) {
	if next == nil || *next == "" {
		return nil, false
	}
	return next, true
}

func (c *sdkClient) ListImages(ctx context.Context, compartment, displayName string) ([]Image, error) {
	var images []Image
	var cursor *string
	for range maxPages {
		response, err := c.compute.ListImages(ociclient.RequestContext(ctx), core.ListImagesRequest{CompartmentId: new(compartment),
			DisplayName: new(displayName), Page: cursor})
		if err != nil {
			return nil, fmt.Errorf("list OCI images: %w", err)
		}
		for _, item := range response.Items {
			images = append(images, image(item))
		}
		var more bool
		if cursor, more = page(response.OpcNextPage); !more {
			return images, nil
		}
	}
	return nil, errors.New("OCI image list exceeds its page bound")
}

func image(item core.Image) Image {
	return Image{ID: deref(item.Id), LifecycleState: string(item.LifecycleState), BillableSizeGB: item.BillableSizeInGBs,
		SHA256: item.FreeformTags[SHA256Tag]}
}

func deref(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func (c *sdkClient) GetImage(ctx context.Context, id string) (Image, error) {
	response, err := c.compute.GetImage(ociclient.RequestContext(ctx), core.GetImageRequest{ImageId: new(id)})
	if err != nil {
		return Image{}, fmt.Errorf("get OCI image: %w", err)
	}
	return image(response.Image), nil
}

func (c *sdkClient) HeadObject(ctx context.Context, namespace, bucket, object string) (bool, map[string]string, error) {
	response, err := c.objects.HeadObject(ociclient.RequestContext(ctx), objectstorage.HeadObjectRequest{NamespaceName: new(namespace),
		BucketName: new(bucket), ObjectName: new(object)})
	if err != nil {
		if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return false, nil, nil
		}
		return false, nil, fmt.Errorf("head OCI object: %w", err)
	}
	return true, response.OpcMeta, nil
}

func (c *sdkClient) UploadObject(ctx context.Context, request UploadRequest) error {
	return c.streamUpload(ctx, request)
}

func (c *sdkClient) ImportImage(ctx context.Context, request ImportRequest) (Image, string, error) {
	response, err := c.compute.CreateImage(ociclient.RequestContext(ctx), core.CreateImageRequest{
		CreateImageDetails: core.CreateImageDetails{
			CompartmentId: new(request.Compartment), DisplayName: new(request.DisplayName),
			FreeformTags: map[string]string{SHA256Tag: request.SHA256},
			LaunchMode:   core.CreateImageDetailsLaunchModeParavirtualized,
			ImageSourceDetails: core.ImageSourceViaObjectStorageTupleDetails{
				NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), ObjectName: new(request.Object),
				SourceImageType: core.ImageSourceDetailsSourceImageTypeQcow2,
				OperatingSystem: new("Custom"), OperatingSystemVersion: new("Custom"),
			},
		},
		// A retry token lets the shared policy replay a lost CreateImage safely.
		OpcRetryToken: new(common.RetryToken()),
	})
	if err != nil {
		return Image{}, "", fmt.Errorf("import OCI image: %w", err)
	}
	return image(response.Image), deref(response.OpcWorkRequestId), nil
}

func (c *sdkClient) GetWorkRequest(ctx context.Context, id string) (WorkRequestStatus, error) {
	response, err := c.workRequest.GetWorkRequest(ociclient.RequestContext(ctx), workrequests.GetWorkRequestRequest{WorkRequestId: new(id)})
	if err != nil {
		return "", fmt.Errorf("get OCI work request: %w", err)
	}
	return WorkRequestStatus(response.Status), nil
}

func (c *sdkClient) streamUpload(ctx context.Context, request UploadRequest) error {
	if len(request.SHA256) != sha256.Size*2 {
		return errors.New("upload requires the expected SHA-256")
	}
	if request.PartSize < 1 || request.Parallelism < 1 {
		return errors.New("upload part size and parallelism must be positive")
	}
	file, err := os.Open(request.Path)
	if err != nil {
		return fmt.Errorf("open QCOW2: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return fmt.Errorf("stat QCOW2: %w", err)
	}
	parts := &partReader{file: file, partSize: request.PartSize, expected: info.Size()}
	digest := sha256.New()
	first, release, err := parts.next(ctx)
	if err != nil {
		return err
	}
	if int64(len(first)) < request.PartSize {
		defer release()
		digest.Write(first)
		if err := matches(digest, request.SHA256); err != nil {
			return err
		}
		sum := md5.Sum(first)
		_, err := c.objects.PutObject(ociclient.RequestContext(ctx), objectstorage.PutObjectRequest{NamespaceName: new(request.Namespace),
			BucketName: new(request.Bucket), ObjectName: new(request.Object), ContentLength: new(int64(len(first))),
			PutObjectBody: io.NopCloser(bytes.NewReader(first)), IfNoneMatch: new("*"), OpcMeta: request.Metadata,
			ContentMD5: new(base64.StdEncoding.EncodeToString(sum[:]))})
		if err != nil {
			return fmt.Errorf("upload OCI object: %w", err)
		}
		return nil
	}
	return c.multipartUpload(ctx, request, parts, digest, first, release)
}

func unitDirectives(source, selectedSection string) map[string]string {
	section := ""
	out := map[string]string{}
	for raw := range strings.SplitSeq(source, "\n") {
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section = strings.Trim(line, "[]")
			continue
		}
		if selectedSection != "" && section != selectedSection {
			continue
		}
		if k, v, ok := strings.Cut(line, "="); ok {
			out[k] = v
		}
	}
	return out
}

func equal(t *testing.T, got, want any) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}

func run(args []string, stdout, stderr io.Writer) error {
	flags := flag.NewFlagSet("jwtsetup", flag.ContinueOnError)
	flags.SetOutput(stderr)
	directory := flags.String("dir", "", "existing private per-run secrets directory")
	cell := flags.String("cell", "", "lowercase regional cell token")
	brokersText := flags.String("brokers", "", "comma-separated broker IDs")
	hostNode := flags.String("host-node", "", "host node identity")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if flags.NArg() != 0 {
		return errors.New("unexpected positional arguments")
	}
	brokers, err := parseBrokers(*brokersText)
	if err != nil {
		return err
	}
	manifest, err := generateFixture(*directory, *cell, brokers, *hostNode)
	if err != nil {
		return err
	}
	encoded, err := json.Marshal(manifest)
	if err != nil {
		return fmt.Errorf("encode public identity manifest: %w", err)
	}
	if _, err := fmt.Fprintln(stdout, string(encoded)); err != nil {
		return fmt.Errorf("write public identity manifest: %w", err)
	}
	return nil
}

func parseBrokers(value string) ([]string, error) {
	if value == "" {
		return nil, errors.New("--brokers must name exactly three broker IDs")
	}
	brokers := strings.Split(value, ",")
	if len(brokers) != maxBrokerCount {
		return nil, errors.New("--brokers must name exactly three broker IDs")
	}
	seen := make(map[string]struct{}, len(brokers))
	for _, broker := range brokers {
		if !validToken(broker) {
			return nil, errors.New("--brokers contains an invalid broker ID")
		}
		if _, exists := seen[broker]; exists {
			return nil, errors.New("--brokers contains a duplicate broker ID")
		}
		seen[broker] = struct{}{}
	}
	return brokers, nil
}

func generateFixture(directory, cell string, brokers []string, hostNode string) (publicManifest, error) {
	if !validToken(cell) || !validToken(hostNode) || len(brokers) != maxBrokerCount {
		return publicManifest{}, errors.New("cell, host node, or broker set is invalid")
	}
	seen := make(map[string]struct{}, len(brokers))
	for _, broker := range brokers {
		if !validToken(broker) || broker == "host" || broker == "operator" || broker == "system" {
			return publicManifest{}, errors.New("broker ID is invalid")
		}
		if _, exists := seen[broker]; exists {
			return publicManifest{}, errors.New("broker IDs must be unique")
		}
		seen[broker] = struct{}{}
	}
	if err := validateSecretsDirectory(directory); err != nil {
		return publicManifest{}, err
	}
	names := outputNames(brokers)
	if err := rejectExistingOutputs(directory, names); err != nil {
		return publicManifest{}, err
	}
	manifest, files, err := makeFixtureFiles(cell, brokers, hostNode)
	if err != nil {
		return publicManifest{}, err
	}
	defer clearFiles(files)
	if err := writeFixtureFiles(directory, names, files); err != nil {
		return publicManifest{}, err
	}
	return manifest, nil
}

func validateSecretsDirectory(directory string) error {
	if directory == "" {
		return errors.New("--dir is required")
	}
	info, err := os.Lstat(directory)
	if err != nil {
		return fmt.Errorf("inspect secrets directory: %w", err)
	}
	if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || info.Mode().Perm() != 0o700 {
		return errors.New("secrets directory must be a real directory with mode 0700")
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || stat.Uid != uint32(os.Getuid()) {
		return errors.New("secrets directory must be owned by the current user")
	}
	return nil
}

func rejectExistingOutputs(directory string, names []string) error {
	for _, name := range names {
		_, err := os.Lstat(filepath.Join(directory, name))
		if err == nil {
			return fmt.Errorf("output already exists: %s", name)
		}
		if !errors.Is(err, os.ErrNotExist) {
			return fmt.Errorf("inspect output %s: %w", name, err)
		}
	}
	return nil
}

func outputNames(brokers []string) []string {
	names := []string{"operator.jwt", "system.jwt", "cell.jwt", "system.creds"}
	for _, broker := range brokers {
		names = append(names, broker+".creds")
	}
	return append(names, "host.creds", "operator.creds", "natsdiag.creds", "broker-ticket.key", "broker-ticket.pub")
}

func makeFixtureFiles(cell string, brokers []string, hostNode string) (publicManifest, map[string][]byte, error) {
	files := make(map[string][]byte, len(outputNames(brokers)))
	manifest, err := buildFixtureFiles(cell, brokers, hostNode, files)
	if err != nil {
		clearFiles(files)
		return publicManifest{}, nil, err
	}
	return manifest, files, nil
}

func buildFixtureFiles(cell string, brokers []string, hostNode string, files map[string][]byte) (publicManifest, error) {
	operatorKey, err := nkeys.CreateOperator()
	if err != nil {
		return publicManifest{}, fmt.Errorf("create operator account key: %w", err)
	}
	defer operatorKey.Wipe()
	systemKey, err := nkeys.CreateAccount()
	if err != nil {
		return publicManifest{}, fmt.Errorf("create system account key: %w", err)
	}
	defer systemKey.Wipe()
	cellKey, err := nkeys.CreateAccount()
	if err != nil {
		return publicManifest{}, fmt.Errorf("create cell account key: %w", err)
	}
	defer cellKey.Wipe()

	operatorID, err := operatorKey.PublicKey()
	if err != nil {
		return publicManifest{}, errors.New("read operator account public identity")
	}
	systemID, err := systemKey.PublicKey()
	if err != nil {
		return publicManifest{}, errors.New("read system account public identity")
	}
	cellID, err := cellKey.PublicKey()
	if err != nil {
		return publicManifest{}, errors.New("read cell account public identity")
	}

	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	operatorJWT, err := operatorClaim.Encode(operatorKey)
	if err != nil {
		return publicManifest{}, fmt.Errorf("sign operator JWT: %w", err)
	}
	systemJWT, err := jwt.NewAccountClaims(systemID).Encode(operatorKey)
	if err != nil {
		return publicManifest{}, fmt.Errorf("sign system account JWT: %w", err)
	}
	cellClaim := jwt.NewAccountClaims(cellID)
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{
		MemoryStorage: cellClaimMemoryBytes, DiskStorage: cellClaimDiskBytes,
		Streams: cellClaimStreams, Consumer: cellClaimConsumers,
	}
	cellJWT, err := cellClaim.Encode(operatorKey)
	if err != nil {
		return publicManifest{}, fmt.Errorf("sign cell account JWT: %w", err)
	}
	files["operator.jwt"] = []byte(operatorJWT + "\n")
	files["system.jwt"] = []byte(systemJWT + "\n")
	files["cell.jwt"] = []byte(cellJWT + "\n")

	manifest := publicManifest{
		OperatorAccount: operatorID, SystemAccount: systemID, CellAccount: cellID,
		Users: make(map[string]string, len(brokers)+4),
	}
	systemCredentials, systemUserID, err := makeCredentials(systemKey, systemID, func(public string) userGrants {
		return userGrants{
			publish:   []string{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"},
			subscribe: []string{inboxPrefix(cell, public) + ".>"},
		}
	})
	if err != nil {
		return publicManifest{}, fmt.Errorf("create in-process system credentials: %w", err)
	}
	files["system.creds"] = systemCredentials
	manifest.Users["system"] = systemUserID

	for _, broker := range brokers {
		credentials, public, err := makeCredentials(cellKey, cellID, func(public string) userGrants {
			publish, subscribe := controllerGrants(cell, broker, public)
			return userGrants{
				publish: publish, subscribe: subscribe, responseMsgs: 1, responseTTL: 5 * time.Second,
			}
		})
		if err != nil {
			return publicManifest{}, fmt.Errorf("create controller credentials for %s: %w", broker, err)
		}
		files[broker+".creds"] = credentials
		manifest.Users[broker] = public
	}

	hostCredentials, hostID, err := makeCredentials(cellKey, cellID, func(public string) userGrants {
		return userGrants{
			publish:   []string{hostObservationSubject(cell, hostNode)},
			subscribe: []string{inboxPrefix(cell, public) + ".>"},
		}
	})
	if err != nil {
		return publicManifest{}, fmt.Errorf("create host credentials: %w", err)
	}
	files["host.creds"] = hostCredentials
	manifest.Users["host"] = hostID

	operatorCredentials, operatorUserID, err := makeCredentials(cellKey, cellID, func(public string) userGrants {
		return userGrants{
			publish:   []string(natscell.BrokerOperatorPublishPermissions(cell)),
			subscribe: []string{inboxPrefix(cell, public) + ".>"},
		}
	})
	if err != nil {
		return publicManifest{}, fmt.Errorf("create operator credentials: %w", err)
	}
	files["operator.creds"] = operatorCredentials
	manifest.Users["operator"] = operatorUserID
	diagnosticCredentials, diagnosticUserID, err := makeCredentials(cellKey, cellID, func(public string) userGrants {
		return userGrants{
			publish:   diagnosticGrants(cell, hostNode),
			subscribe: []string{inboxPrefix(cell, public) + ".>"},
		}
	})
	if err != nil {
		return publicManifest{}, fmt.Errorf("create diagnostic credentials: %w", err)
	}
	files["natsdiag.creds"] = diagnosticCredentials
	manifest.Users["natsdiag"] = diagnosticUserID

	ticketPublic, ticketPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return publicManifest{}, fmt.Errorf("create broker ticket signing key: %w", err)
	}
	defer clear(ticketPrivate)
	files["broker-ticket.key"] = []byte(base64.StdEncoding.EncodeToString(ticketPrivate) + "\n")
	files["broker-ticket.pub"] = []byte(base64.StdEncoding.EncodeToString(ticketPublic) + "\n")
	return manifest, nil
}

func makeCredentials(accountKey nkeys.KeyPair, accountID string, grantsFor func(string) userGrants) ([]byte, string, error) {
	userKey, err := nkeys.CreateUser()
	if err != nil {
		return nil, "", fmt.Errorf("create NATS user key: %w", err)
	}
	defer userKey.Wipe()
	public, err := userKey.PublicKey()
	if err != nil {
		return nil, "", errors.New("read NATS user public identity")
	}
	grants := grantsFor(public)
	claim := jwt.NewUserClaims(public)
	claim.IssuerAccount = accountID
	claim.Pub.Allow = slices.Clone(grants.publish)
	claim.Sub.Allow = slices.Clone(grants.subscribe)
	if grants.responseMsgs != 0 || grants.responseTTL != 0 {
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: grants.responseMsgs, Expires: grants.responseTTL}
	}
	raw, err := claim.Encode(accountKey)
	if err != nil {
		return nil, "", fmt.Errorf("sign NATS user JWT: %w", err)
	}
	seed, err := userKey.Seed()
	if err != nil {
		return nil, "", errors.New("read NATS user seed for decorated credentials")
	}
	defer clear(seed)
	credentials, err := jwt.FormatUserConfig(raw, seed)
	if err != nil {
		return nil, "", errors.New("format decorated NATS user credentials")
	}
	return credentials, public, nil
}

func controllerGrants(cell, broker, public string) ([]string, []string) {
	root := "ts.orch.v1." + cell
	publish := []string{
		root + ".>", "ts.control." + cell + ".>", "$JS.API.>", "$KV.>", "$O.>",
		"$JS.ACK.TS_DELIVERY_INTENTS.TS_DELIVERY_WORKER.>",
		"ts.broker." + cell + ".ticket.>", "ts.broker." + cell + ".fence.>",
	}
	subscribe := []string{
		inboxPrefix(cell, public) + ".>",
		root + ".agent.*.observation.*", root + ".delivery.artifact.admit",
		root + ".host.register", root + ".placement.apply", root + ".broker.claim.apply",
		root + ".managed-update.prepare",
		root + ".backup.operation",
		"ts.broker." + cell + ".ticket.>", "ts.broker." + cell + ".fence." + broker,
		root + ".terminal.>",
	}
	return publish, subscribe
}

