func (r *Runtime) ApplyCellClaim(ctx context.Context, sequence uint64, raw string) error {
	if r == nil || r.server == nil || r.resolver == nil || r.systemConn == nil ||
		sequence == 0 || raw == "" {
		return errors.New("production cell claim application is unavailable")
	}
	r.claimMu.Lock()
	defer r.claimMu.Unlock()
	if sequence < r.appliedSequence {
		return errors.New("cell claim sequence is stale")
	}
	if r.bridge != nil {
		r.bridge.FenceClaim(sequence)
	}
	if claim, err := jwt.DecodeAccountClaims(raw); err != nil || !r.SignedByPinnedOperator(claim) {
		return errors.New("cell claim is not signed by the pinned operator")
	}
	// Store runs the contract and issued-at checks; only then is the claim
	// installed, locally and directly. The server ignores CLAIMS.UPDATE
	// requests (see accountResolver.IsTrackingUpdate), so no routed or
	// client-sent claim can skip these checks.
	if err := r.resolver.Store(r.resolver.cell, raw); err != nil {
		return err
	}
	account, err := r.server.LookupAccount(r.resolver.cell)
	if err != nil {
		return err
	}
	current, err := r.server.Accountz(&server.AccountzOptions{Account: r.resolver.cell})
	if err != nil {
		return err
	}
	if current.Account == nil {
		return errors.New("cell account is not loaded")
	}
	if current.Account.Jwt != raw {
		if err := r.server.UpdateAccountClaimJWT(account, raw); err != nil {
			return fmt.Errorf("install cell account claim: %w", err)
		}
		current, err = r.server.Accountz(&server.AccountzOptions{Account: r.resolver.cell})
		if err != nil || current.Account == nil || current.Account.Jwt != raw {
			return errors.New("cell JWT update lacks local exact readback")
		}
	}
	r.appliedSequence = sequence
	return nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func (r *Runtime) WaitForCluster(ctx context.Context, replicas int) error {
	if replicas < 1 || replicas > 5 || replicas%2 == 0 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	quorum := replicas/2 + 1
	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	for {
		if r.server != nil && !r.server.Running() {
			return ErrEmbeddedServerStopped
		}
		if r.Ready() && (r.server == nil || r.peerCount() >= quorum && r.metadataReady(quorum)) {
			probeCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
			_, err := r.js.AccountInfo(probeCtx)
			cancel()
			if err == nil {
				return nil
			}
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("wait for %d regional NATS peers: %w", quorum, ctx.Err())
		case <-ticker.C:
		}
	}
}

// FullClusterReady distinguishes a missing peer from a permanent inability to
// place a new R3/R5 stream. It does not claim every peer is caught up.
func (r *Runtime) FullClusterReady(replicas int) bool {
	return r != nil && r.Ready() && (r.server == nil ||
		r.peerCount() >= replicas && r.metadataReady(replicas))
}

func (r *Runtime) metadataReady(required int) bool {
	if required == 1 {
		return true
	}
	info, err := r.server.Jsz(nil)
	if err != nil || info.Meta == nil || info.Meta.Leader == "" || info.Meta.Size < required {
		return false
	}
	// Follower-local metadata can report an online peer as Current=false even
	// while the leader reports it caught up. Requiring Current on every local
	// view can therefore prevent a healthy follower from ever becoming ready.
	online := 1 // This embedded server is running.
	for _, peer := range info.Meta.Replicas {
		if peer != nil && !peer.Offline && !peer.Pending {
			online++
		}
	}
	return online >= required
}

func (r *Runtime) peerCount() int {
	if r.server == nil {
		return 1
	}
	routes, err := r.server.Routez(nil)
	if err != nil {
		return 0
	}
	ids := map[string]struct{}{routes.ID: {}}
	for _, route := range routes.Routes {
		if route.RemoteID != "" {
			ids[route.RemoteID] = struct{}{}
		}
	}
	return len(ids)
}

func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

func serverOptions(cfg Config) (*server.Options, error) {
	return serverOptionsForStart(cfg, false)
}

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}
	if identityRekey && (e.InterRegion != nil || e.Link != nil) {
		options.LeafNode = server.LeafNodeOpts{}
	}
	if cfg.Replicas > 1 {
		for _, raw := range e.Routes {
			route, err := url.Parse(raw)
			if err != nil || route.Host == "" || route.User != nil || route.Scheme != "nats-route" {
				return nil, fmt.Errorf("invalid NATS route %q", raw)
			}
			options.Routes = append(options.Routes, route)
		}
	}
	if cfg.Replicas > 1 && e.RouteTLS.complete() {
		// Routes reload a renewed leaf or CA bundle on their next handshake.
		routeTLS, err := NewReloadingTLS(e.RouteTLS, "route")
		if err != nil {
			return nil, err
		}
		options.Cluster.TLSConfig = routeTLS.PeerConfig()
	}
	seenKeys := make(map[string]struct{}, len(e.Users))
	for _, user := range e.Users {
		if !nkeys.IsValidPublicUserKey(user.PublicKey) {
			return nil, errors.New("invalid user NKey in embedded NATS users")
		}
		if _, exists := seenKeys[user.PublicKey]; exists {
			return nil, errors.New("duplicate embedded NATS user key")
		}
		seenKeys[user.PublicKey] = struct{}{}
		permissions, err := userPermissions(cfg.Cell, user)
		if err != nil {
			return nil, err
		}
		options.Nkeys = append(options.Nkeys, &server.NkeyUser{Nkey: user.PublicKey, Permissions: permissions})
	}
	if e.RoutePasswordFile != "" {
		secret, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("read NATS route secret: %w", err)
		}
		defer clear(secret)
		password := strings.TrimSpace(string(secret))
		if len(password) < 16 {
			return nil, errors.New("NATS route secret must be at least 16 bytes")
		}
		options.Cluster.Username = e.RouteUser
		options.Cluster.Password = password
		for _, route := range options.Routes {
			route.User = url.UserPassword(e.RouteUser, password)
		}
	}
	return options, nil
}

func clientOptions(cfg Config) ([]nats.Option, error) {
	connectTimeout := 12 * time.Second
	if cfg.ClientRole == "host" {
		connectTimeout = 3 * time.Second
	}
	options := []nats.Option{nats.Name("terrascale-" + cfg.Cell + "-" + cfg.Instance), nats.Timeout(connectTimeout),
		nats.ErrorHandler(ErrorHandler)}
	// Renewal applies to every authentication mode: an NKey-seed client has
	// no JWT to reload but must still present a renewed certificate.
	var materials *clientMaterialSource
	if cfg.ReloadClientMaterial != nil {
		materials = newClientMaterialSource(cfg, "")
	}
	if cfg.CredentialsFile != "" {
		data, err := readPrivateFile(cfg.CredentialsFile, 64<<10)
		if err != nil {
			return nil, fmt.Errorf("regional JWT credentials: %w", err)
		}
		pair, err := nkeys.ParseDecoratedUserNKey(data)
		clear(data)
		if err != nil {
			return nil, fmt.Errorf("regional JWT credentials: %w", err)
		}
		public, err := pair.PublicKey()
		pair.Wipe()
		if err != nil {
			return nil, err
		}
		options = append(options, nats.CustomInboxPrefix(inboxPrefix(cfg.Cell, public)))
		source := materials
		if source == nil {
			source = newClientMaterialSource(cfg, public)
		}
		source.user = public
		// The JWT and its signature come from one resolved file per handshake.
		var handshake ClientMaterial
		options = append(options, nats.UserJWT(func() (string, error) {
			handshake = source.current()
			data, err := readPrivateFile(handshake.CredentialsFile, 64<<10)
			if err != nil {
				return "", err
			}
			defer clear(data)
			return nkeys.ParseDecoratedJWT(data)
		}, func(nonce []byte) ([]byte, error) {
			path := handshake.CredentialsFile
			if path == "" {
				path = cfg.CredentialsFile
			}
			return signNKeyFile(path, nonce)
		}))
	}
	if cfg.NKeySeedFile != "" {
		data, err := readPrivateFile(cfg.NKeySeedFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("regional NKey seed: %w", err)
		}
		pair, err := nkeys.ParseDecoratedUserNKey(data)
		clear(data)
		if err != nil {
			return nil, fmt.Errorf("regional NKey seed: %w", err)
		}
		public, err := pair.PublicKey()
		pair.Wipe()
		if err != nil {
			return nil, err
		}
		options = append(options, nats.CustomInboxPrefix(inboxPrefix(cfg.Cell, public)))
		options = append(options, nats.Nkey(public, func(nonce []byte) ([]byte, error) {
			return signNKeyFile(cfg.NKeySeedFile, nonce)
		}))
	}
	if cfg.TLS.complete() && cfg.Embedded == nil {
		tlsConfig, err := loadTLS(cfg.TLS, false)
		if err != nil {
			return nil, err
		}
		dialer := &tlsFirstDialer{config: tlsConfig, timeout: connectTimeout}
		if materials != nil {
			dialer.reload = materials.tlsConfig
		}
		if len(cfg.OperatorForward) != 0 {
			_, destinations, err := operatorForwarding(cfg)
			if err != nil {
				return nil, err
			}
			dialer.forward = destinations
			options = append(options, nats.IgnoreDiscoveredServers())
		}
		options = append(options, nats.SetCustomDialer(dialer))
	}
	return options, nil
}

func startBridge(s *server.Server, address string, tlsConfig *tls.Config, account string) (*Bridge, error) {
	if s == nil || tlsConfig == nil || account == "" {
		return nil, errors.New("production broker bridge is incomplete")
	}
	listener, err := tls.Listen("tcp", address, tlsConfig)
	if err != nil {
		return nil, fmt.Errorf("listen for regional broker clients: %w", err)
	}
	b := &Bridge{server: s, listener: listener, account: account, pairs: make(map[*bridgePair]struct{}), listeners: make(map[net.Listener]struct{})}
	go b.accept(listener)
	return b, nil
}

// Every additional listener shares the primary listener's mTLS and ticket
// fence, including closing its established sessions when that fence expires.
func (b *Bridge) listen(address string, config *tls.Config) (net.Listener, error) {
	b.mu.Lock()
	if b.closed {
		b.mu.Unlock()
		return nil, ErrBridgeClosed
	}
	b.mu.Unlock()
	listener, err := tls.Listen("tcp", address, config)
	if err != nil {
		return nil, fmt.Errorf("listen for regional broker clients at %s: %w", address, err)
	}
	b.mu.Lock()
	if b.closed {
		b.mu.Unlock()
		_ = listener.Close()
		return nil, ErrBridgeClosed
	}
	b.listeners[listener] = struct{}{}
	go b.accept(listener)
	b.mu.Unlock()
	return &bridgeListener{Listener: listener, bridge: b}, nil
}

func (b *Bridge) Addr() net.Addr { return b.listener.Addr() }

func (b *Bridge) Status() BridgeStatus {
	if b == nil {
		return BridgeStatus{}
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	status := BridgeStatus{Open: b.open && time.Now().Before(b.deadline), ClaimSequence: b.sequence,
		ActiveSessions: len(b.pairs), Deadline: b.deadline}
	if b.jwt != "" {
		digest := sha256.Sum256([]byte(b.jwt))
		status.JWTHash = hex.EncodeToString(digest[:])
	}
	return status
}

// OpenUntil requires local proof that NATS applied the exact durable account
// JWT. The caller must first verify an authority ticket and conservative
// monotonic deadline; this method does not mint or verify tickets.
func (b *Bridge) OpenUntil(sequence uint64, rawJWT string, deadline time.Time) error {
	if b == nil || sequence == 0 || rawJWT == "" || !time.Now().Before(deadline) {
		return errors.New("broker bridge ticket is invalid or expired")
	}
	if _, err := b.server.LookupAccount(b.account); err != nil {
		return fmt.Errorf("load broker account: %w", err)
	}
	accountz, err := b.server.Accountz(&server.AccountzOptions{Account: b.account})
	if err != nil || accountz.Account == nil || accountz.Account.Jwt != rawJWT {
		return errors.New("broker account JWT was not applied locally")
	}
	b.mu.Lock()
	if b.closed || sequence < b.floor {
		b.mu.Unlock()
		return errors.New("broker bridge is closed or claim sequence is stale")
	}
	var pairs map[*bridgePair]struct{}
	if b.open && (b.sequence != sequence || b.jwt != rawJWT) {
		pairs = b.fenceLocked()
	}
	b.sequence, b.jwt, b.deadline, b.open = sequence, rawJWT, deadline, true
	if b.timer != nil {
		b.timer.Stop()
	}
	b.timer = time.AfterFunc(time.Until(deadline), func() {
		b.mu.Lock()
		var expired map[*bridgePair]struct{}
		if b.open && b.sequence == sequence && b.deadline.Equal(deadline) {
			expired = b.fenceLocked()
		}
		b.mu.Unlock()
		closeBridgeExternal(expired)
	})
	b.mu.Unlock()
	closeBridgeExternal(pairs)
	return nil
}

func (b *Bridge) serve(external net.Conn, listener net.Listener) {
	defer external.Close()
	if err := external.SetDeadline(time.Now().Add(5 * time.Second)); err != nil {
		return
	}
	if err := external.(*tls.Conn).Handshake(); err != nil {
		return
	}
	if err := external.SetDeadline(time.Time{}); err != nil {
		return
	}
	internal, err := b.server.InProcessConnForAccount(b.account)
	if err != nil {
		return
	}
	pair := &bridgePair{external: external, internal: internal, listener: listener}
	b.mu.Lock()
	_, additional := b.listeners[listener]
	if b.closed || listener != b.listener && !additional || !b.open || !time.Now().Before(b.deadline) {
		b.mu.Unlock()
		pair.close()
		return
	}
	b.pairs[pair] = struct{}{}
	b.mu.Unlock()
	done := make(chan struct{}, 2)
	go func() { _, _ = io.Copy(internal, external); done <- struct{}{} }()
	go func() { _, _ = io.Copy(external, internal); done <- struct{}{} }()
	<-done
	pair.close()
	<-done
	b.mu.Lock()
	delete(b.pairs, pair)
	b.mu.Unlock()
}

func Open(ctx context.Context, cfg Config) (*Service, error) {
	if cfg.Conn == nil || cfg.JS == nil || !validCell(cfg.Cell) || cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 || cfg.ArtifactStoreMaxBytes < 0 {
		return nil, fmt.Errorf("%w: delivery service configuration", ErrInvalid)
	}
	artifactStoreMaxBytes := cfg.ArtifactStoreMaxBytes
	if artifactStoreMaxBytes == 0 {
		artifactStoreMaxBytes = DefaultArtifactStoreMaxBytes
	}
	// A larger quota already in force came from the cell spec
	// (artifact_store), which the leader re-applies; a restart must not
	// shrink the store under an upload before then.
	if existing, err := cfg.JS.Stream(ctx, "OBJ_"+ArtifactBucket); err == nil {
		artifactStoreMaxBytes = max(artifactStoreMaxBytes, existing.CachedInfo().Config.MaxBytes)
	} else if !errors.Is(err, jetstream.ErrStreamNotFound) {
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	s := &Service{js: cfg.JS, config: cfg}
	var err error
	s.artifacts, err = cfg.JS.CreateOrUpdateObjectStore(ctx, artifactStoreConfig(cfg.Replicas, artifactStoreMaxBytes))
	if err != nil {
		return nil, fmt.Errorf("artifact store: %w", err)
	}
	stream, err := cfg.JS.Stream(ctx, "OBJ_"+ArtifactBucket)
	if err != nil {
		if errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect artifact store limits: %w", ErrStoreNotReady, err)
		}
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	streamInfo, err := stream.Info(ctx)
	if err != nil {
		if errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect artifact store limits: %w", ErrStoreNotReady, err)
		}
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	if streamInfo.Config.MaxBytes != artifactStoreMaxBytes || streamInfo.Config.Discard != jetstream.DiscardNew {
		return nil, fmt.Errorf("%w: artifact store must enforce the configured byte quota with discard-new", ErrInvalid)
	}
	s.admissions, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: AdmissionBucket, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, History: 1})
	if err != nil {
		return nil, fmt.Errorf("artifact admissions: %w", err)
	}
	s.operations, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: OperationBucket, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, History: 4})
	if err != nil {
		return nil, fmt.Errorf("delivery operations: %w", err)
	}
	_, err = cfg.JS.CreateOrUpdateStream(ctx, jetstream.StreamConfig{Name: IntentStream, Subjects: []string{IntentSubject(cfg.Cell)}, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, Retention: jetstream.WorkQueuePolicy, Discard: jetstream.DiscardNew, MaxMsgs: 100_000, MaxBytes: 1 << 30, MaxMsgSize: MaxIntentBytes + 8192, Duplicates: 2 * time.Minute})
	if err != nil {
		return nil, fmt.Errorf("delivery intent stream: %w", err)
	}
	s.consumer, err = cfg.JS.CreateOrUpdateConsumer(ctx, IntentStream, intentConsumerConfig(cfg.Cell))
	if err != nil {
		return nil, fmt.Errorf("delivery intent consumer: %w", err)
	}
	return s, nil
}

func NewController(ctx context.Context, cfg ControllerConfig) (*Controller, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.Conn == nil || cfg.JS == nil || cfg.Artifacts == nil || cfg.HostMutations == nil || len(cfg.ResponseKey) != ed25519.PrivateKeySize {
		return nil, errors.New("controller requires NATS, JetStream, ordered host mutations, artifact store and Ed25519 response key")
	}
	if cfg.AuthorityEpoch == nil || cfg.AuthorityGuard == nil {
		return nil, errors.New("controller requires authority epoch and guard")
	}
	managedEffectGate := cfg.ManagedEffectGate
	if managedEffectGate == nil {
		if gate, ok := cfg.HostMutations.(interface {
			BeginActiveWorkloadEffect(context.Context, uint64, authority.WorkloadScope) (func(), error)
		}); ok {
			managedEffectGate = gate.BeginActiveWorkloadEffect
		}
	}
	if cfg.ManagedRegistrationVerifier != nil && managedEffectGate == nil {
		return nil, errors.New("managed host registration requires a terminal effect gate")
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("invalid host state replica count")
	}
	state := cfg.State
	if state == nil {
		var err error
		state, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: stateBucket, History: 2, MaxValueSize: 64 << 10, MaxBytes: 256 << 20, Storage: jetstream.FileStorage, Replicas: replicas})
		if err != nil {
			return nil, fmt.Errorf("open host state: %w", err)
		}
	}
	status, err := state.Status(ctx)
	if err != nil {
		if cfg.State == nil && errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect host state: %w", ErrStateNotReady, err)
		}
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	if err := rejectObsoleteRetirementState(ctx, state, cfg.Cell); err != nil {
		return nil, err
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, fmt.Errorf("open ordered control log: %w", err)
		}
	}
	cacheCtx, cacheCancel := context.WithCancel(context.Background())
	return &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations,
		managedVerifier: cfg.ManagedRegistrationVerifier, managedDesiredVerifier: cfg.ManagedDesiredVerifier,
		managedEffectGate: managedEffectGate, materialProvider: cfg.ManagedMaterialProvider,
		credentialFloor: cfg.ManagedCredentialFloor, volumeInspector: cfg.ManagedVolumeInspector, runtimeEffects: cfg.RuntimeEffects,
		containerMaterial: cfg.ContainerMaterialProvider, registryAdmission: cfg.RegistryAdmissionProvider,
		taskLoadRoles:    cfg.TaskLoadRoles,
		functionMaterial: cfg.FunctionMaterialProvider,
		terraBaseCA:      cfg.TerraBaseCA, roleIdentity: cfg.RoleIdentity, nodeAddress: cfg.NodeAddress, restartGate: cfg.RestartGate, artifacts: cfg.Artifacts, responseKey: cfg.ResponseKey, ready: make(chan struct{}),
		authorityEpoch: cfg.AuthorityEpoch, authorityGuard: cfg.AuthorityGuard, authorityLeader: cfg.AuthorityLeader,
		cacheContext: cacheCtx, cacheCancel: cacheCancel}, nil
}

func NewJetStreamStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, intents AdmittedIntentReader) (Store, error) {
	if !validToken(cell) || js == nil || intents == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("placement store requires cell, JetStream, admitted intent reader and valid replica count")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       stateBucketName,
		Description:  "Durable regional TerraBase placement member state",
		History:      2,
		MaxValueSize: maxStateBytes,
		MaxBytes:     128 << 20,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open placement member state: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("read placement member state status: %w", err)
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("placement state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	return &jetStreamStore{cell: cell, state: kv, intents: intents}, nil
}

func loadAuthoritySigner(cfg options) (ed25519.PrivateKey, error) {
	if cfg.ephemeralTestSigner {
		_, private, err := ed25519.GenerateKey(rand.Reader)
		return private, err
	}
	if !filepath.IsAbs(cfg.authoritySeedFile) || filepath.Clean(cfg.authoritySeedFile) != cfg.authoritySeedFile {
		return nil, errors.New("authority seed path must be clean and absolute")
	}
	if !lowerSHA256.MatchString(cfg.authorityPublicSHA256) {
		return nil, errors.New("authority public key SHA-256 pin is required")
	}
	info, err := os.Lstat(cfg.authoritySeedFile)
	if err != nil {
		return nil, err
	}
	if err := checkAuthoritySeedInfo(info); err != nil {
		return nil, err
	}
	fd, err := unix.Open(cfg.authoritySeedFile, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), cfg.authoritySeedFile)
	defer file.Close()
	opened, err := file.Stat()
	if err != nil || !os.SameFile(info, opened) {
		return nil, errors.New("authority seed changed before reading")
	}
	if err := checkAuthoritySeedInfo(opened); err != nil {
		return nil, err
	}
	seed := make([]byte, ed25519.SeedSize)
	defer clear(seed)
	if _, err := io.ReadFull(file, seed); err != nil {
		return nil, err
	}
	after, err := os.Lstat(cfg.authoritySeedFile)
	if err != nil || !os.SameFile(opened, after) || opened.Size() != after.Size() || !opened.ModTime().Equal(after.ModTime()) {
		return nil, errors.New("authority seed changed while reading")
	}
	if err := checkAuthoritySeedInfo(after); err != nil {
		return nil, err
	}
	private := ed25519.NewKeyFromSeed(seed)
	publicHash := sha256.Sum256(private.Public().(ed25519.PublicKey))
	pinnedHash, err := hex.DecodeString(cfg.authorityPublicSHA256)
	if err != nil || subtle.ConstantTimeCompare(publicHash[:], pinnedHash) != 1 {
		clear(private)
		return nil, errors.New("authority public key does not match the independent pin")
	}
	return private, nil
}

func checkAuthoritySeedInfo(info os.FileInfo) error {
	if !info.Mode().IsRegular() || info.Mode() != 0600 || info.Size() != ed25519.SeedSize {
		return errors.New("authority seed must be a protected 32-byte regular file")
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || (stat.Uid != 0 && stat.Uid != uint32(os.Geteuid())) {
		return errors.New("authority seed must be owned by root or the current user")
	}
	return nil
}

func record(path string) (inputFile, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return inputFile{}, errors.New("input path must be clean and absolute")
	}
	info, err := os.Lstat(path)
	if err != nil {
		return inputFile{}, err
	}
	if !info.Mode().IsRegular() {
		return inputFile{}, errors.New("input is not a direct regular file")
	}
	file, err := os.Open(path)
	if err != nil {
		return inputFile{}, err
	}
	defer file.Close()
	opened, err := file.Stat()
	if err != nil || !os.SameFile(info, opened) {
		return inputFile{}, errors.New("input changed before hashing")
	}
	hasher := sha256.New()
	if _, err := io.Copy(hasher, file); err != nil {
		return inputFile{}, err
	}
	after, err := os.Lstat(path)
	if err != nil || !os.SameFile(opened, after) || opened.Size() != after.Size() || !opened.ModTime().Equal(after.ModTime()) {
		return inputFile{}, errors.New("input changed while hashing")
	}
	return inputFile{Path: path, SHA256: hex.EncodeToString(hasher.Sum(nil))}, nil
}

func writeExclusive(path string, content []byte) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	count, err := file.Write(content)
	if err != nil {
		_ = file.Close()
		return err
	}
	if count != len(content) {
		_ = file.Close()
		return io.ErrShortWrite
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	return file.Close()
}

func makeVolume(path, uuid string) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return err
	}
	if err := file.Truncate(256 << 20); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	command := exec.Command("mkfs.ext4", "-q", "-F", "-U", uuid, path)
	output, err := command.CombinedOutput()
	if err != nil {
		return fmt.Errorf("format fixture volume: %w: %s", err, output)
	}
	return nil
}

